struct Tape {
    enum Op { CONST, INPUT, ADD, MUL, SIN, EXP };
    struct Node {
        double v;   // forward value
        double g;   // accumulated gradient
        Op op;
        int a, b;   // input ids (-1 for constants/inputs)
    };
    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back(Node{v, 0.0, CONST, -1, -1});
        return static_cast<int>(nodes.size()) - 1;
    }
    int input(double v) {
        nodes.push_back(Node{v, 0.0, INPUT, -1, -1});
        return static_cast<int>(nodes.size()) - 1;
    }
    int add(int a, int b) {
        nodes.push_back(Node{nodes[a].v + nodes[b].v, 0.0, ADD, a, b});
        return static_cast<int>(nodes.size()) - 1;
    }
    int mul(int a, int b) {
        nodes.push_back(Node{nodes[a].v * nodes[b].v, 0.0, MUL, a, b});
        return static_cast<int>(nodes.size()) - 1;
    }
    int sin_(int a) {
        nodes.push_back(Node{std::sin(nodes[a].v), 0.0, SIN, a, -1});
        return static_cast<int>(nodes.size()) - 1;
    }
    int exp_(int a) {
        nodes.push_back(Node{std::exp(nodes[a].v), 0.0, EXP, a, -1});
        return static_cast<int>(nodes.size()) - 1;
    }

    double value(int node) const { return nodes[node].v; }

    void backward(int root) {
        for (auto& n : nodes) n.g = 0.0;
        nodes[root].g = 1.0;
        // Reverse recording order: every consumer of node i was recorded
        // after i, so it has already contributed its adjoint by the time
        // we process i.
        for (int i = static_cast<int>(nodes.size()) - 1; i >= 0; --i) {
            const Node& n = nodes[i];
            if (n.op == CONST) continue; // constants carry no gradient
            switch (n.op) {
                case ADD:
                    nodes[n.a].g += n.g;
                    nodes[n.b].g += n.g;
                    break;
                case MUL:
                    nodes[n.a].g += n.g * nodes[n.b].v;
                    nodes[n.b].g += n.g * nodes[n.a].v;
                    break;
                case SIN:
                    nodes[n.a].g += n.g * std::cos(nodes[n.a].v);
                    break;
                case EXP:
                    nodes[n.a].g += n.g * n.v; // d/dx e^x = e^x
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const { return nodes[node].g; }
};
